package com.example.lending.domain;

import java.time.LocalDate;
import java.time.temporal.ChronoUnit;
import java.util.Objects;
import java.util.UUID;

public class Loan {

    static final int LOAN_PERIOD_DAYS = 14;
    static final long LATE_FEE_PER_DAY = 100;

    private final UUID id;
    private final UUID bookId;
    private final UUID memberId;
    private final LocalDate loanedAt;
    private final LocalDate dueAt;
    private LocalDate returnedAt;

    private Loan(UUID id, UUID bookId, UUID memberId, LocalDate loanedAt, LocalDate dueAt, LocalDate returnedAt) {
        this.id = Objects.requireNonNull(id, "id");
        this.bookId = Objects.requireNonNull(bookId, "bookId");
        this.memberId = Objects.requireNonNull(memberId, "memberId");
        this.loanedAt = Objects.requireNonNull(loanedAt, "loanedAt");
        this.dueAt = Objects.requireNonNull(dueAt, "dueAt");
        if (dueAt.isBefore(loanedAt)) {
            throw new IllegalArgumentException("dueAt must not be before loanedAt");
        }
        this.returnedAt = returnedAt;
    }

    // 대출 생성은 Book.loanTo를 통해서만 (대출 가능 여부 규칙을 우회하지 않도록 package-private)
    static Loan start(UUID bookId, UUID memberId, LocalDate loanedAt) {
        return new Loan(UUID.randomUUID(), bookId, memberId, loanedAt, loanedAt.plusDays(LOAN_PERIOD_DAYS), null);
    }

    // 반납 처리는 Book.returnLoan을 통해서만 (책 상태와 대출 상태가 함께 바뀌도록 package-private)
    void markReturned(LocalDate returnedAt) {
        if (this.returnedAt != null) {
            throw new AlreadyReturnedException(id);
        }
        Objects.requireNonNull(returnedAt, "returnedAt");
        if (returnedAt.isBefore(loanedAt)) {
            throw new IllegalArgumentException("returnedAt must not be before loanedAt");
        }
        this.returnedAt = returnedAt;
    }

    public static Loan reconstitute(UUID id, UUID bookId, UUID memberId, LocalDate loanedAt, LocalDate dueAt,
                                    LocalDate returnedAt) {
        return new Loan(id, bookId, memberId, loanedAt, dueAt, returnedAt);
    }

    public boolean isReturned() {
        return returnedAt != null;
    }

    public boolean isOverdue(LocalDate today) {
        return today.isAfter(dueAt);
    }

    public UUID getId() {
        return id;
    }

    public UUID getBookId() {
        return bookId;
    }

    public UUID getMemberId() {
        return memberId;
    }

    public LocalDate getLoanedAt() {
        return loanedAt;
    }

    public LocalDate getDueAt() {
        return dueAt;
    }

    public LocalDate getReturnedAt() {
        return returnedAt;
    }

    // 기한 당일 반납은 연체가 아니다. 기한을 넘긴 날짜 수만큼 연체일이 된다.
    public long getOverdueDays() {
        if (returnedAt == null) {
            throw new IllegalStateException("loan is not returned yet: " + id);
        }
        if (!returnedAt.isAfter(dueAt)) {
            return 0;
        }
        return ChronoUnit.DAYS.between(dueAt, returnedAt);
    }

    public long getLateFee() {
        return getOverdueDays() * LATE_FEE_PER_DAY;
    }
}
package com.example.lending.domain;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import java.util.Objects;
import java.util.UUID;

public class Book {

    private final UUID id;
    private final String title;
    private BookStatus status;
    // 예약 대기열. 맨 앞이 가장 먼저 대출할 수 있는 예약자다
    private final List<Reservation> reservations;

    private Book(UUID id, String title, BookStatus status, List<Reservation> reservations) {
        this.id = Objects.requireNonNull(id, "id");
        if (title == null || title.isBlank()) {
            throw new IllegalArgumentException("title must not be blank");
        }
        this.title = title;
        this.status = Objects.requireNonNull(status, "status");
        this.reservations = new ArrayList<>(Objects.requireNonNull(reservations, "reservations"));
    }

    public static Book register(String title) {
        return new Book(UUID.randomUUID(), title, BookStatus.AVAILABLE, List.of());
    }

    public static Book reconstitute(UUID id, String title, BookStatus status, List<Reservation> reservations) {
        return new Book(id, title, status, reservations);
    }

    // 대출 중인 책에만 예약할 수 있다. 줄의 맨 뒤에 선다
    public Reservation reserve(UUID memberId) {
        if (status == BookStatus.DISCARDED) {
            throw new BookDiscardedException(id);
        }
        if (status == BookStatus.AVAILABLE) {
            throw new BookAvailableException(id);
        }
        if (reservations.stream().anyMatch(r -> r.getMemberId().equals(memberId))) {
            throw new AlreadyReservedException(id, memberId);
        }
        Reservation reservation = Reservation.place(memberId);
        reservations.add(reservation);
        return reservation;
    }

    // 예약이 남아 있으면 맨 앞 예약자만 빌릴 수 있고, 빌리는 순간 그 예약은 소진된다
    public Loan loanTo(UUID memberId, LocalDate loanedAt) {
        if (status == BookStatus.DISCARDED) {
            throw new BookDiscardedException(id);
        }
        if (status == BookStatus.ON_LOAN) {
            throw new BookAlreadyOnLoanException(id);
        }
        if (!reservations.isEmpty()) {
            if (!reservations.get(0).getMemberId().equals(memberId)) {
                throw new BookReservedForOtherException(id);
            }
            reservations.remove(0);
        }
        Loan loan = Loan.start(id, memberId, loanedAt);
        status = BookStatus.ON_LOAN;
        return loan;
    }

    // 대출 중인 책은 폐기할 수 없다. 이미 폐기된 책을 다시 폐기해도 상태는 그대로 둔다
    public void discard() {
        if (status == BookStatus.ON_LOAN) {
            throw new CannotDiscardBookOnLoanException(id);
        }
        status = BookStatus.DISCARDED;
    }

    public void returnLoan(Loan loan, LocalDate returnedAt) {
        if (!loan.getBookId().equals(id)) {
            throw new IllegalArgumentException("loan does not belong to book: " + id);
        }
        loan.markReturned(returnedAt);
        status = BookStatus.AVAILABLE;
    }

    public UUID getId() {
        return id;
    }

    public String getTitle() {
        return title;
    }

    public BookStatus getStatus() {
        return status;
    }

    public List<Reservation> getReservations() {
        return List.copyOf(reservations);
    }
}
package com.example.lending.domain;

import java.util.Objects;
import java.util.Set;
import java.util.UUID;

public class Member {

    public static final int MAX_CONCURRENT_LOANS = 5;

    // 후원자 회원은 대출 권수 제한이 없다
    private static final Set<UUID> UNLIMITED_LOAN_MEMBER_IDS = Set.of(
            UUID.fromString("11111111-1111-1111-1111-111111111111"),
            UUID.fromString("22222222-2222-2222-2222-222222222222"),
            UUID.fromString("33333333-3333-3333-3333-333333333333"));

    private final UUID id;
    private final String name;
    private boolean suspended;

    private Member(UUID id, String name, boolean suspended) {
        this.id = Objects.requireNonNull(id, "id");
        if (name == null || name.isBlank()) {
            throw new IllegalArgumentException("name must not be blank");
        }
        this.name = name;
        this.suspended = suspended;
    }

    public static Member register(String name) {
        return register(UUID.randomUUID(), name);
    }

    public static Member register(UUID id, String name) {
        return new Member(id, name, false);
    }

    public static Member reconstitute(UUID id, String name, boolean suspended) {
        return new Member(id, name, suspended);
    }

    public void suspend() {
        this.suspended = true;
    }

    public void unsuspend() {
        this.suspended = false;
    }

    public void ensureCanBorrow(long activeLoanCount) {
        if (suspended) {
            throw new MemberSuspendedException(id);
        }
        if (UNLIMITED_LOAN_MEMBER_IDS.contains(id)) {
            return;
        }
        if (activeLoanCount >= MAX_CONCURRENT_LOANS) {
            throw new LoanLimitExceededException(id);
        }
    }

    public UUID getId() {
        return id;
    }

    public String getName() {
        return name;
    }

    public boolean isSuspended() {
        return suspended;
    }
}
package com.example.lending.application.service;

import com.example.lending.application.port.in.LoanBookUseCase;
import com.example.lending.application.port.out.CheckCreditPort;
import com.example.lending.application.port.out.CountActiveLoansPort;
import com.example.lending.application.port.out.LoadBookPort;
import com.example.lending.application.port.out.LoadMemberPort;
import com.example.lending.application.port.out.SaveBookPort;
import com.example.lending.application.port.out.SaveCreditCheckPort;
import com.example.lending.application.port.out.SaveLoanPort;
import com.example.lending.domain.Book;
import com.example.lending.domain.BookNotFoundException;
import com.example.lending.domain.CreditCheck;
import com.example.lending.domain.CreditRejectedException;
import com.example.lending.domain.Loan;
import com.example.lending.domain.Member;
import com.example.lending.domain.MemberNotFoundException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.LocalDate;
import java.util.Objects;

@Service
@Transactional
public class LoanBookService implements LoanBookUseCase {

    private final LoadMemberPort loadMemberPort;
    private final CountActiveLoansPort countActiveLoansPort;
    private final LoadBookPort loadBookPort;
    private final SaveBookPort saveBookPort;
    private final SaveLoanPort saveLoanPort;
    private final CheckCreditPort checkCreditPort;
    private final SaveCreditCheckPort saveCreditCheckPort;

    public LoanBookService(LoadMemberPort loadMemberPort,
                           CountActiveLoansPort countActiveLoansPort,
                           LoadBookPort loadBookPort,
                           SaveBookPort saveBookPort,
                           SaveLoanPort saveLoanPort,
                           CheckCreditPort checkCreditPort,
                           SaveCreditCheckPort saveCreditCheckPort) {
        this.loadMemberPort = loadMemberPort;
        this.countActiveLoansPort = countActiveLoansPort;
        this.loadBookPort = loadBookPort;
        this.saveBookPort = saveBookPort;
        this.saveLoanPort = saveLoanPort;
        this.checkCreditPort = checkCreditPort;
        this.saveCreditCheckPort = saveCreditCheckPort;
    }

    // 신용 거절은 조회 기록을 남겨야 하므로 롤백하지 않는다.
    // 거절 전에는 책과 대출을 저장하지 않으므로 책 상태는 그대로 대출 가능하다
    @Override
    @Transactional(noRollbackFor = CreditRejectedException.class)
    public Loan loanBook(LoanBookCommand command) {
        Member member = loadMemberPort.loadMemberForUpdate(command.memberId())
                .orElseThrow(() -> new MemberNotFoundException(command.memberId()));
        member.ensureCanBorrow(countActiveLoansPort.countActiveLoans(member.getId()));
        Book book = loadBookPort.loadBookForUpdate(command.bookId())
                .orElseThrow(() -> new BookNotFoundException(command.bookId()));
        LocalDate loanedAt = Objects.requireNonNullElseGet(command.loanedAt(), LocalDate::now);
        // 대출 가능 여부를 먼저 확인해, 대출할 수 없는 책에는 외부 신용조회를 하지 않는다
        Loan loan = book.loanTo(member.getId(), loanedAt);
        CreditCheck creditCheck = checkCreditPort.check(member.getId(), member.getName());
        if (!creditCheck.approved()) {
            saveCreditCheckPort.saveCreditCheck(member.getId(), book.getId(), null, creditCheck);
            throw new CreditRejectedException(member.getId());
        }
        saveBookPort.saveBook(book);
        saveLoanPort.saveLoan(loan);
        saveCreditCheckPort.saveCreditCheck(member.getId(), book.getId(), loan.getId(), creditCheck);
        return loan;
    }
}
package com.example.lending.application.service;

import com.example.lending.application.port.in.ReturnBookUseCase;
import com.example.lending.application.port.out.LoadBookPort;
import com.example.lending.application.port.out.LoadLoanPort;
import com.example.lending.application.port.out.SaveBookPort;
import com.example.lending.application.port.out.SaveLoanPort;
import com.example.lending.domain.Book;
import com.example.lending.domain.BookNotFoundException;
import com.example.lending.domain.Loan;
import com.example.lending.domain.LoanNotFoundException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.LocalDate;
import java.util.Objects;

@Service
@Transactional
public class ReturnBookService implements ReturnBookUseCase {

    private final LoadLoanPort loadLoanPort;
    private final LoadBookPort loadBookPort;
    private final SaveBookPort saveBookPort;
    private final SaveLoanPort saveLoanPort;

    public ReturnBookService(LoadLoanPort loadLoanPort,
                             LoadBookPort loadBookPort,
                             SaveBookPort saveBookPort,
                             SaveLoanPort saveLoanPort) {
        this.loadLoanPort = loadLoanPort;
        this.loadBookPort = loadBookPort;
        this.saveBookPort = saveBookPort;
        this.saveLoanPort = saveLoanPort;
    }

    @Override
    public Loan returnBook(ReturnBookCommand command) {
        Loan loan = loadLoanPort.loadLoanForUpdate(command.loanId())
                .orElseThrow(() -> new LoanNotFoundException(command.loanId()));
        Book book = loadBookPort.loadBook(loan.getBookId())
                .orElseThrow(() -> new BookNotFoundException(loan.getBookId()));
        LocalDate returnedAt = Objects.requireNonNullElseGet(command.returnedAt(), LocalDate::now);
        book.returnLoan(loan, returnedAt);
        saveBookPort.saveBook(book);
        saveLoanPort.saveLoan(loan);
        return loan;
    }
}
package com.example.lending.application.service;

import com.example.lending.application.port.in.DiscardBookUseCase;
import com.example.lending.application.port.out.LoadBookPort;
import com.example.lending.application.port.out.SaveBookPort;
import com.example.lending.domain.Book;
import com.example.lending.domain.BookNotFoundException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
@Transactional
public class DiscardBookService implements DiscardBookUseCase {

    private final LoadBookPort loadBookPort;
    private final SaveBookPort saveBookPort;

    public DiscardBookService(LoadBookPort loadBookPort, SaveBookPort saveBookPort) {
        this.loadBookPort = loadBookPort;
        this.saveBookPort = saveBookPort;
    }

    @Override
    public Book discardBook(DiscardBookCommand command) {
        Book book = loadBookPort.loadBookForUpdate(command.bookId())
                .orElseThrow(() -> new BookNotFoundException(command.bookId()));
        book.discard();
        saveBookPort.saveBook(book);
        return book;
    }
}
package com.example.lending.application.service;

import com.example.lending.application.port.in.SuspendMemberUseCase;
import com.example.lending.application.port.out.LoadMemberPort;
import com.example.lending.application.port.out.SaveMemberPort;
import com.example.lending.domain.Member;
import com.example.lending.domain.MemberNotFoundException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.UUID;

@Service
@Transactional
public class SuspendMemberService implements SuspendMemberUseCase {

    private final LoadMemberPort loadMemberPort;
    private final SaveMemberPort saveMemberPort;

    public SuspendMemberService(LoadMemberPort loadMemberPort, SaveMemberPort saveMemberPort) {
        this.loadMemberPort = loadMemberPort;
        this.saveMemberPort = saveMemberPort;
    }

    // 대출 요청과 같은 회원 행 잠금을 쓰므로, 진행 중인 대출 판단이 끝난 뒤에 정지가 반영된다
    @Override
    public Member suspendMember(UUID memberId) {
        Member member = loadMemberPort.loadMemberForUpdate(memberId)
                .orElseThrow(() -> new MemberNotFoundException(memberId));
        member.suspend();
        saveMemberPort.saveMember(member);
        return member;
    }
}
package com.example.lending.application.service;

import com.example.lending.application.port.in.UnsuspendMemberUseCase;
import com.example.lending.application.port.out.LoadMemberPort;
import com.example.lending.application.port.out.SaveMemberPort;
import com.example.lending.domain.Member;
import com.example.lending.domain.MemberNotFoundException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.UUID;

@Service
@Transactional
public class UnsuspendMemberService implements UnsuspendMemberUseCase {

    private final LoadMemberPort loadMemberPort;
    private final SaveMemberPort saveMemberPort;

    public UnsuspendMemberService(LoadMemberPort loadMemberPort, SaveMemberPort saveMemberPort) {
        this.loadMemberPort = loadMemberPort;
        this.saveMemberPort = saveMemberPort;
    }

    // 정지 때와 같은 회원 행 잠금을 써서 대출 판단과 순서를 맞춘다
    @Override
    public Member unsuspendMember(UUID memberId) {
        Member member = loadMemberPort.loadMemberForUpdate(memberId)
                .orElseThrow(() -> new MemberNotFoundException(memberId));
        member.unsuspend();
        saveMemberPort.saveMember(member);
        return member;
    }
}

