import java.time.Instant;
import java.util.ArrayList;
import java.util.List;
import java.util.UUID;

@Entity
@Table(name = "credit_check")
public class CreditCheckJpaEntity {

    @Id
    private UUID id;

    @Column(nullable = false)
    private UUID memberId;

    @Column(nullable = false)
    private UUID bookId;

    // 거절된 조회는 대출이 없으므로 null
    private UUID loanId;

    @Column(nullable = false)
    private boolean approved;

    private int score;

    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "credit_check_reason", joinColumns = @JoinColumn(name = "credit_check_id"))
    @Column(name = "reason_code", nullable = false)
    private List<String> reasonCodes = new ArrayList<>();

    @Column(nullable = false)
    private Instant checkedAt;

    private String providerName;

    private String providerVersion;

    protected CreditCheckJpaEntity() {
    }

    public CreditCheckJpaEntity(UUID id, UUID memberId, UUID bookId, UUID loanId, boolean approved, int score,
                                List<String> reasonCodes, Instant checkedAt, String providerName,
                                String providerVersion) {
        this.id = id;
        this.memberId = memberId;
        this.bookId = bookId;
        this.loanId = loanId;
        this.approved = approved;
        this.score = score;
        this.reasonCodes = new ArrayList<>(reasonCodes);
        this.checkedAt = checkedAt;
        this.providerName = providerName;
        this.providerVersion = providerVersion;
    }

    public UUID getId() {
        return id;
    }

    public UUID getMemberId() {
        return memberId;
    }

    public UUID getBookId() {
        return bookId;
    }

    public UUID getLoanId() {
        return loanId;
    }

    public boolean isApproved() {
        return approved;
    }

    public int getScore() {
        return score;
    }

    public List<String> getReasonCodes() {
        return reasonCodes;
    }

    public Instant getCheckedAt() {
        return checkedAt;
    }

    public String getProviderName() {
        return providerName;
    }

    public String getProviderVersion() {
        return providerVersion;
    }
}
