package com.example.lending;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;

import java.util.UUID;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@SpringBootTest
@AutoConfigureMockMvc
class MemberSuspensionIntegrationTest {

    @Autowired
    MockMvc mockMvc;

    @Autowired
    ObjectMapper objectMapper;

    @Test
    void new_member_is_not_suspended() throws Exception {
        String memberId = registerMember("정수빈");

        mockMvc.perform(get("/members/{memberId}", memberId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.suspended").value(false));
    }

    @Test
    void suspended_member_is_shown_as_suspended_and_can_be_unsuspended() throws Exception {
        String memberId = registerMember("이서준");

        mockMvc.perform(post("/members/{memberId}/suspend", memberId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.suspended").value(true));

        mockMvc.perform(get("/members/{memberId}", memberId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.suspended").value(true));

        mockMvc.perform(post("/members/{memberId}/unsuspend", memberId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.suspended").value(false));

        mockMvc.perform(get("/members/{memberId}", memberId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.suspended").value(false));
    }

    @Test
    void suspended_member_cannot_borrow_a_book() throws Exception {
        String memberId = registerMember("최유나");
        String bookId = registerBook("Suspended Member Book");
        String loanRequest = objectMapper.writeValueAsString(new LoanBody(bookId, memberId));

        mockMvc.perform(post("/members/{memberId}/suspend", memberId))
                .andExpect(status().isOk());

        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON).content(loanRequest))
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("MEMBER_SUSPENDED"));
    }

    @Test
    void member_can_borrow_again_after_unsuspend() throws Exception {
        String memberId = registerMember("강도윤");
        String bookId = registerBook("Unsuspended Member Book");
        String loanRequest = objectMapper.writeValueAsString(new LoanBody(bookId, memberId));

        mockMvc.perform(post("/members/{memberId}/suspend", memberId))
                .andExpect(status().isOk());
        mockMvc.perform(post("/members/{memberId}/unsuspend", memberId))
                .andExpect(status().isOk());

        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON).content(loanRequest))
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.bookId").value(bookId));
    }

    @Test
    void suspending_unknown_member_returns_404() throws Exception {
        mockMvc.perform(post("/members/{memberId}/suspend", UUID.randomUUID()))
                .andExpect(status().isNotFound());
    }

    @Test
    void unsuspending_unknown_member_returns_404() throws Exception {
        mockMvc.perform(post("/members/{memberId}/unsuspend", UUID.randomUUID()))
                .andExpect(status().isNotFound());
    }

    private String registerMember(String name) throws Exception {
        String registered = mockMvc.perform(post("/members")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"name\":\"" + name + "\"}"))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(registered).get("memberId").asText();
    }

    private String registerBook(String title) throws Exception {
        String registered = mockMvc.perform(post("/books")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"title\":\"" + title + "\"}"))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        JsonNode book = objectMapper.readTree(registered);
        return book.get("id").asText();
    }

    record LoanBody(String bookId, String memberId) {
    }
}
